CREATE TABLE public.plan_invite_links(token uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_id uuid NOT NULL REFERENCES public.plans(id) ON DELETE CASCADE,inviter uuid NOT NULL REFERENCES public.profiles(id),UNIQUE(plan_id,inviter)); GRANT SELECT,INSERT ON public.plan_invite_links TO authenticated; GRANT ALL ON public.plan_invite_links TO service_role; ALTER TABLE public.plan_invite_links ENABLE ROW LEVEL SECURITY; CREATE POLICY "own plan links" ON public.plan_invite_links FOR SELECT TO authenticated USING(inviter=auth.uid() AND public.is_plan_member(plan_id,auth.uid())); CREATE POLICY "attendees create public plan links" ON public.plan_invite_links FOR INSERT TO authenticated WITH CHECK(inviter=auth.uid() AND public.is_plan_member(plan_id,auth.uid()) AND EXISTS(SELECT 1 FROM public.plans WHERE id=plan_id AND NOT is_private));
CREATE FUNCTION public.invite_teaser(_token uuid) RETURNS TABLE(plan_id uuid,title text,image_url text,area_label text,starts_at timestamptz,inviter_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.title,p.image_url,p.area_label,p.starts_at,split_part(pr.name,' ',1) FROM public.plan_invite_links l JOIN public.plans p ON p.id=l.plan_id JOIN public.profiles pr ON pr.id=l.inviter WHERE l.token=_token AND NOT p.is_private AND public.is_plan_member(p.id,l.inviter) AND (auth.uid() IS NULL OR NOT public.people_blocked(l.inviter,auth.uid())) $$; REVOKE ALL ON FUNCTION public.invite_teaser(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.invite_teaser(uuid) TO anon,authenticated;
CREATE FUNCTION public.respond_invite_link(_token uuid,_status text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.plan_invite_links; iid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to RSVP'; END IF; SELECT * INTO l FROM public.plan_invite_links WHERE token=_token; IF l.token IS NULL OR l.inviter=auth.uid() OR public.people_blocked(l.inviter,auth.uid()) OR NOT public.is_plan_member(l.plan_id,l.inviter) OR NOT EXISTS(SELECT 1 FROM public.plans WHERE id=l.plan_id AND NOT is_private) THEN RAISE EXCEPTION 'Invite unavailable'; END IF; INSERT INTO public.plan_invites(plan_id,inviter,invitee) VALUES(l.plan_id,l.inviter,auth.uid()) ON CONFLICT(plan_id,invitee) DO NOTHING; SELECT id INTO iid FROM public.plan_invites WHERE plan_id=l.plan_id AND invitee=auth.uid(); RETURN public.respond_invite(iid,_status); END $$; REVOKE ALL ON FUNCTION public.respond_invite_link(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.respond_invite_link(uuid,text) TO authenticated;
CREATE FUNCTION public.notify_join_details() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.plans; BEGIN IF NEW.status='approved' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN SELECT * INTO p FROM public.plans WHERE id=NEW.plan_id; INSERT INTO public.notifications(user_id,plan_id,title) VALUES(NEW.user_id,p.id,'You are going: '||p.title||' · '||to_char(p.starts_at AT TIME ZONE 'UTC','DD Mon HH24:MI')||' UTC. Bring: '||COALESCE(NULLIF(p.what_to_bring,''),'Check with the host')||'. Address unlocks 2 hours before.'); END IF; RETURN NEW; END $$; CREATE TRIGGER notify_join_details AFTER INSERT OR UPDATE ON public.join_requests FOR EACH ROW EXECUTE FUNCTION public.notify_join_details();